var i=`0164-spaghetti-aglio-e-olio`;var a=`world-0164`;var s=`IT`;var n=`southern-europe`;var o=4;var r=17;var l={en:`Spaghetti Aglio e Olio`,ua:`Спагеті альйо е ольйо`};var g={en:`A classic dish from Italy, featuring garlic, spaghetti, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: часник, спагеті, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 4 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 4 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:4,i:[[`garlic`,6,`clove`],[`extra-virgin-olive-oil`,75,`ml`],[`crushed-red-pepper`,5,`g`]]},{en:`Cook the pasta in generously salted boiling water for about 10 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 10 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:10,i:[[`spaghetti`,400,`g`],[`water`,1600,`ml`],[`table-salt`,10,`g`]]},{en:`Toss the cooked pasta with the sauce, adding a splash of reserved pasta water until everything is evenly coated.`,ua:`Змішайте готову пасту із соусом, додаючи потроху збережену воду з-під пасти, доки соус рівномірно вкриє її.`,t:[`pasta-finishing-in-sauce`,`tossing`],m:3,i:[[`parsley`,25,`g`]]}];var h={slug:i,id:a,country:`IT`,region:n,servings:4,minutes:17,title:l,text:g,steps:u};export{s as country,h as default,a as id,r as minutes,n as region,o as servings,i as slug,u as steps,g as text,l as title};